// Controller-owned no-explicit-limits Job membership only. No suspension/kill/VM/debug APIs.
using System;using System.Collections.Generic;using System.Collections.Concurrent;using System.Diagnostics;using System.Threading;using System.ComponentModel;using System.IO;using System.Runtime.InteropServices;using System.Security.Cryptography;using System.Text;
public sealed class OwnJobMember {public int Pid;public long Created;public string Image,Sha256;public bool MembershipVerified;public uint FileVolume,FileIndexHigh,FileIndexLow;public long FileBytes;public uint ExitCode;public bool TerminalObserved;internal IntPtr Handle;}
public sealed class OwnUpgradeJob:IDisposable {
 [StructLayout(LayoutKind.Sequential)]struct FileInfoNative {public uint Attributes;public System.Runtime.InteropServices.ComTypes.FILETIME Created,Accessed,Written;public uint Volume,SizeHigh,SizeLow,Links,IndexHigh,IndexLow;}
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandle(IntPtr file,out FileInfoNative info);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr CreateJobObject(IntPtr attributes,string name);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool AssignProcessToJobObject(IntPtr job,IntPtr process);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool QueryInformationJobObject(IntPtr job,int info,IntPtr data,uint length,out uint returned);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool IsProcessInJob(IntPtr process,IntPtr job,out bool result);
 [DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(uint rights,bool inherit,int pid);
 [DllImport("kernel32.dll",SetLastError=true)]static extern uint GetProcessId(IntPtr process);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetProcessTimes(IntPtr h,out long a,out long b,out long c,out long d);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool QueryFullProcessImageName(IntPtr h,int flags,StringBuilder path,ref int length);
 [DllImport("kernel32.dll")]static extern uint WaitForSingleObject(IntPtr h,uint milliseconds);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetExitCodeProcess(IntPtr h,out uint code);
 [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr h);
 IntPtr job;long baseline;int oldPid;ConcurrentDictionary<int,OwnJobMember> members=new ConcurrentDictionary<int,OwnJobMember>();Thread watcher;ManualResetEvent stop=new ManualResetEvent(false);public volatile string ObserverError;public bool Assigned,NoExplicitLimits=true,KillOnClose=false;public int Queries,MaximumMembers=64;public List<OwnJobMember> Rows {get{return new List<OwnJobMember>(members.Values);}}
 static Exception Error(string text){return new Win32Exception(Marshal.GetLastWin32Error(),text);}
 public OwnUpgradeJob(IntPtr oldProcess,int pid,long created){long a,b,c,d;if(GetProcessId(oldProcess)!=(uint)pid||WaitForSingleObject(oldProcess,0)!=258||!GetProcessTimes(oldProcess,out a,out b,out c,out d)||a!=created)throw new Exception("Retained old creation identity required before private Job assignment");baseline=created;oldPid=pid;job=CreateJobObject(IntPtr.Zero,null);if(job==IntPtr.Zero)throw Error("Create private Job");if(!AssignProcessToJobObject(job,oldProcess)){CloseHandle(job);job=IntPtr.Zero;throw Error("Assign only own retained app to no-explicit-limits Job");}bool inside;if(!IsProcessInJob(oldProcess,job,out inside)||!inside){CloseHandle(job);job=IntPtr.Zero;throw Error("Own old Job membership unavailable");}Assigned=true;}
 public void StartWatch(){if(watcher!=null)throw new Exception("Observer already started");watcher=new Thread(()=>{try{var clock=Stopwatch.StartNew();while(!stop.WaitOne(0)&&clock.Elapsed.TotalSeconds<180){Poll();stop.WaitOne(40);}}catch(Exception error){ObserverError=error.GetType().Name+": "+error.Message;}});watcher.IsBackground=true;watcher.Start();}
 public void StopWatch(){stop.Set();if(watcher!=null&&!watcher.Join(3000))throw new Exception("Retained own observer did not stop");if(ObserverError!=null)throw new Exception("Own Job observer failed: "+ObserverError);}
 public void Poll(){
  if(job==IntPtr.Zero||++Queries>7200)throw new Exception("Private Job query count bound");int bytes=8+64*IntPtr.Size;IntPtr data=Marshal.AllocHGlobal(bytes);
  try{uint returned;if(!QueryInformationJobObject(job,3,data,(uint)bytes,out returned))throw Error("Bounded Job membership query failed");if(returned<8||returned>(uint)bytes)throw new Exception("Job membership returned byte count invalid");int assigned=Marshal.ReadInt32(data,0),count=Marshal.ReadInt32(data,4);if(assigned<0||assigned>64||count<0||count>64||assigned!=count||returned<(uint)(8+count*IntPtr.Size))throw new Exception("Private Job membership count cap/partial inventory");
   for(int i=0;i<count;i++){long value=Marshal.ReadIntPtr(data,8+i*IntPtr.Size).ToInt64();if(value<=0||value>Int32.MaxValue)throw new Exception("Job member PID range");int pid=(int)value;if(pid==oldPid||members.ContainsKey(pid))continue;if(members.Count>=64)throw new Exception("Observed Job member cap");
    // Only a PID JUST returned by our private created Job is eligible for this reduced-rights handle.
    IntPtr h=OpenProcess(0x101000,false,pid);if(h==IntPtr.Zero)throw Error("Retain returned own Job member");
    try{bool inside;long a,b,c,d;if(GetProcessId(h)!=(uint)pid||!IsProcessInJob(h,job,out inside)||!inside||!GetProcessTimes(h,out a,out b,out c,out d)||a<baseline)throw new Exception("Retained Job member PID/start/membership changed");var path=new StringBuilder(32768);int length=path.Capacity;if(!QueryFullProcessImageName(h,0,path,ref length)||length<=0||length>=32768)throw Error("Own member image path");var row=new OwnJobMember{Pid=pid,Created=a,Image=path.ToString(),MembershipVerified=true,Handle=h};if(!members.TryAdd(pid,row))throw new Exception("Own Job PID duplicate");h=IntPtr.Zero;}finally{if(h!=IntPtr.Zero)CloseHandle(h);}
   }
  }finally{Marshal.FreeHGlobal(data);}
 }
 static FileInfoNative FileIdentity(FileStream file){FileInfoNative info;if(!GetFileInformationByHandle(file.SafeFileHandle.DangerousGetHandle(),out info)||(info.IndexHigh==0&&info.IndexLow==0)||(info.Attributes&16)!=0)throw Error("Opened own image file identity unavailable");return info;}
 static bool SameFile(FileInfoNative a,FileInfoNative b){return a.Volume==b.Volume&&a.IndexHigh==b.IndexHigh&&a.IndexLow==b.IndexLow&&a.SizeHigh==b.SizeHigh&&a.SizeLow==b.SizeLow;}
 public string Hash(int pid){OwnJobMember row;if(!members.TryGetValue(pid,out row))throw new Exception("Only retained Job member may be hashed");Check(row);using(var input=new FileStream(row.Image,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var hash=SHA256.Create()){if(input.Length<=0||input.Length>64*1024*1024)throw new Exception("Own candidate file size cap");var before=FileIdentity(input);row.Sha256=BitConverter.ToString(hash.ComputeHash(input)).Replace("-","").ToLowerInvariant();var after=FileIdentity(input);if(!SameFile(before,after))throw new Exception("Opened own image identity changed during hash");row.FileVolume=before.Volume;row.FileIndexHigh=before.IndexHigh;row.FileIndexLow=before.IndexLow;row.FileBytes=input.Length;}Check(row);return row.Sha256;}
 public bool SameInstalledFile(int pid,string expected){OwnJobMember row;if(!members.TryGetValue(pid,out row))throw new Exception("Unknown native own Job member");Check(row);using(var actual=new FileStream(row.Image,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var known=new FileStream(expected,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){var a=FileIdentity(actual);var b=FileIdentity(known);return SameFile(a,b)&&a.Volume==row.FileVolume&&a.IndexHigh==row.FileIndexHigh&&a.IndexLow==row.FileIndexLow;}}

 void Check(OwnJobMember row){bool inside;long a,b,c,d;uint wait=WaitForSingleObject(row.Handle,0);if(GetProcessId(row.Handle)!=(uint)row.Pid||!GetProcessTimes(row.Handle,out a,out b,out c,out d)||a!=row.Created||(wait!=0&&wait!=258)||(wait==258&&(!IsProcessInJob(row.Handle,job,out inside)||!inside)))throw new Exception("Retained own Job identity changed");}
 public IntPtr HandleOf(int pid){OwnJobMember row;if(!members.TryGetValue(pid,out row))throw new Exception("Unknown private Job member");Check(row);return row.Handle;}
 public bool Terminal(int pid){OwnJobMember row;if(!members.TryGetValue(pid,out row))throw new Exception("Unknown private Job terminal");Check(row);uint wait=WaitForSingleObject(row.Handle,0);if(wait==258)return false;if(wait!=0)throw Error("Own member terminal wait failed");uint code;if(!GetExitCodeProcess(row.Handle,out code))throw Error("Own member exit status");row.TerminalObserved=true;row.ExitCode=code;return true;}
 public void Dispose(){StopWatch();foreach(var row in members.Values)if(row.Handle!=IntPtr.Zero){CloseHandle(row.Handle);row.Handle=IntPtr.Zero;}if(job!=IntPtr.Zero){CloseHandle(job);job=IntPtr.Zero;}}
}
